import {validPhoto} from './stock-photo-model.js?v=20261023-desk10';
import clip from './vendor/polygon-clipping.js';
export const DEFAULT_FOAM={width:600,height:400,thickness:50,base:5,margin:10,spacing:8};
const finite=n=>typeof n==='number'&&Number.isFinite(n);
export const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
export const clone=v=>JSON.parse(JSON.stringify(v));
export function extent(shape){const points=shape.flat(2);return {minX:Math.min(...points.map(p=>p[0])),minY:Math.min(...points.map(p=>p[1])),maxX:Math.max(...points.map(p=>p[0])),maxY:Math.max(...points.map(p=>p[1]))};}
export function close(ring){const r=ring.map(p=>[...p]);if(r.length&&r[0].some((v,i)=>v!==r.at(-1)[i]))r.push([...r[0]]);return r;}
export function normalizePaths(paths){const shape=clip.union(...paths.map(p=>[close(p)])),b=extent(shape);return shape.map(poly=>poly.map(r=>r.map(([x,y])=>[x-b.minX,y-b.minY])));}
export function moveShape(shape,dx,dy){return shape.map(p=>p.map(r=>r.map(([x,y])=>[x+dx,y+dy])));}
export function posed(tool,shape=tool.shape){const a=tool.rotation*Math.PI/180,c=Math.cos(a),s=Math.sin(a),rot=p=>p.map(r=>r.map(([x,y])=>[x*c-y*s,x*s+y*c])),base=tool.shape.map(rot),b=extent(base);return shape.map(rot).map(p=>p.map(r=>r.map(([x,y])=>[x-b.minX+tool.x,y-b.minY+tool.y])));}
export function unpose(tool,[x,y]){const a=tool.rotation*Math.PI/180,c=Math.cos(a),s=Math.sin(a),rot=tool.shape.map(p=>p.map(r=>r.map(([x,y])=>[x*c-y*s,x*s+y*c]))),b=extent(rot),dx=x-tool.x+b.minX,dy=y-tool.y+b.minY;return [dx*c+dy*s,-dx*s+dy*c];}
export function shapeArea(shape){return shape.reduce((total,p)=>total+p.reduce((sum,r,i)=>{let a=0;for(let j=0;j<r.length-1;j++)a+=r[j][0]*r[j+1][1]-r[j+1][0]*r[j][1];return sum+(i?-1:1)*Math.abs(a/2);},0),0);}
export function rectShape(x,y,w,h){return [[[ [x,y],[x+w,y],[x+w,y+h],[x,y+h],[x,y] ]]];}
export function pointIn(shape,p){const inside=r=>{let yes=false;for(let i=0,j=r.length-1;i<r.length;j=i++)if((r[i][1]>p[1])!==(r[j][1]>p[1])&&p[0]<(r[j][0]-r[i][0])*(p[1]-r[i][1])/(r[j][1]-r[i][1])+r[i][0])yes=!yes;return yes;};return shape.some(poly=>inside(poly[0])&&!poly.slice(1).some(inside));}
export function zonesFor(tool){return (tool.zones||[]).map(z=>({...z,shape:clip.intersection(tool.shape,z.shape)})).filter(z=>z.shape.length&&z.depth>tool.depth);}
export function depthLayers(tools){const regions=tools.flatMap(t=>[{depth:t.depth,shape:posed(t)},...zonesFor(t).map(z=>({depth:z.depth,shape:posed(t,z.shape)}))]);const depths=[...new Set(regions.map(r=>r.depth))].sort((a,b)=>a-b);return depths.map(depth=>({depth,shape:clip.union(...regions.filter(r=>r.depth>=depth).map(r=>r.shape))}));}
export function surfaces(tools,foam){const layers=depthLayers(tools);return {top:layers.length?clip.difference(rectShape(0,0,foam.width,foam.height),layers[0].shape):rectShape(0,0,foam.width,foam.height),layers:layers.map((l,i)=>({...l,floor:i===layers.length-1?l.shape:clip.difference(l.shape,layers[i+1].shape),from:i?layers[i-1].depth:0}))};}
export function checkLayout(tools,foam){
 const issues=[],geometry=tools.map(t=>{const shape=posed(t);return {shape,b:extent(shape)};}),areas=(foam.keepouts||[]).map(z=>({...z,b:extent(z.shape)}));
 const apart=(a,b)=>a.maxX+foam.spacing<b.minX||b.maxX+foam.spacing<a.minX||a.maxY+foam.spacing<b.minY||b.maxY+foam.spacing<a.minY;
 if(foam.photo&&(Math.abs(foam.width-foam.photo.width)>.01||Math.abs(foam.height-foam.photo.height)>.01))issues.push({type:'photo-scale',tools:[],message:'Foam dimensions changed. Recalibrate or remove the photo; tools have not been rescaled.'});
 if(foam.photo?.verification&&!foam.photo.verification.passed)issues.push({type:'photo-reference',tools:[],message:'Photo reference check failed. Recalibrate the foam photo before export.'});
 for(const [i,t] of tools.entries()){
  const {shape,b}=geometry[i];
  if(b.minX<foam.margin-.01||b.minY<foam.margin-.01||b.maxX>foam.width-foam.margin+.01||b.maxY>foam.height-foam.margin+.01)issues.push({type:'bounds',tools:[i],message:`${t.name}: outside edge margin`});
  if(t.depth>foam.thickness-foam.base+.001||(t.zones||[]).some(z=>z.depth>foam.thickness-foam.base+.001))issues.push({type:'depth',tools:[i],message:`${t.name}: insufficient foam beneath pocket`});
  for(const zone of areas){if(apart(b,zone.b))continue;const overlap=clip.intersection(shape,zone.shape);if(shapeArea(overlap)>.01||foam.spacing>0&&shapesCloserThan(shape,zone.shape,foam.spacing-.05))issues.push({type:'keepout',tools:[i],message:`${t.name}: too close to no-cut area ${zone.name}`});}
  for(let j=0;j<i;j++){const a=geometry[j];if(apart(b,a.b)||(t.lock&&t.lock===tools[j].lock))continue;const overlap=clip.intersection(shape,a.shape);if(shapeArea(overlap)>.01)continue;if(foam.spacing>0&&shapesCloserThan(shape,a.shape,foam.spacing-.05))issues.push({type:'spacing',tools:[j,i],message:`${tools[j].name} / ${t.name}: less than ${foam.spacing} mm apart`});}
 }
 return issues;
}
function shapesCloserThan(a,b,limit){
 if(limit<=0)return false;const squared=limit*limit;
 const flatten=shape=>shape.flatMap(poly=>poly.flatMap(ring=>ring.slice(0,-1)));
 const segments=shape=>shape.flatMap(poly=>poly.flatMap(ring=>ring.slice(1).map((w,i)=>{const v=ring[i];return {v,w,minX:Math.min(v[0],w[0])-limit,maxX:Math.max(v[0],w[0])+limit,minY:Math.min(v[1],w[1])-limit,maxY:Math.max(v[1],w[1])+limit};})));
 const near=(points,edges)=>{for(const p of points)for(const {v,w,minX,maxX,minY,maxY} of edges){if(p[0]<minX||p[0]>maxX||p[1]<minY||p[1]>maxY)continue;const dx=w[0]-v[0],dy=w[1]-v[1],t=Math.max(0,Math.min(1,((p[0]-v[0])*dx+(p[1]-v[1])*dy)/(dx*dx+dy*dy||1))),x=p[0]-v[0]-t*dx,y=p[1]-v[1]-t*dy;if(x*x+y*y<squared)return true;}return false;};
 return near(flatten(a),segments(b))||near(flatten(b),segments(a));
}

export function findPlacement(tool,placed,foam){const blockers=[...placed.map(t=>extent(posed(t))),...(foam.keepouts||[]).map(z=>extent(z.shape))],size=extent(posed({...tool,x:0,y:0})),xs=[foam.margin,...blockers.map(b=>b.maxX+foam.spacing)],ys=[foam.margin,...blockers.map(b=>b.maxY+foam.spacing)];for(const y of ys.sort((a,b)=>a-b))for(const x of xs.sort((a,b)=>a-b))if(x+size.maxX<=foam.width-foam.margin&&y+size.maxY<=foam.height-foam.margin&&blockers.every(b=>x+size.maxX+foam.spacing<=b.minX+.001||b.maxX+foam.spacing<=x+.001||y+size.maxY+foam.spacing<=b.minY+.001||b.maxY+foam.spacing<=y+.001))return {x,y};return null;}
export function autoArrange(tools,foam){const result=[];for(const t of clone(tools)){const position=findPlacement(t,result,foam);if(!position)throw Error('No automatic arrangement found. Rotate or move tools manually, or enlarge the foam.');Object.assign(t,position);result.push(t);}return result;}
export function validateFoam(data){if(!data||typeof data!=='object')throw Error('Invalid foam project');const f=data.foam;for(const k of ['width','height'])if(!finite(f?.[k])||f[k]<25||f[k]>2500)throw Error('Foam width and height must be 25–2500 mm');if(!finite(f.thickness)||f.thickness<2||f.thickness>200)throw Error('Foam thickness must be 2–200 mm');for(const k of ['base','margin','spacing'])if(!finite(f[k])||f[k]<0||f[k]>100)throw Error('Invalid foam margin, spacing or base');if(f.base>=f.thickness||f.margin*2>=Math.min(f.width,f.height))throw Error('Foam margins leave no usable space');if(!Array.isArray(data.tools)||data.tools.length>100)throw Error('Maximum 100 tools');let points=0;const shape=s=>{if(!Array.isArray(s)||!s.length||s.length>100)throw Error('Invalid profile');for(const p of s){if(!Array.isArray(p)||!p.length)throw Error('Invalid profile');for(const r of p){if(!Array.isArray(r)||r.length<4)throw Error('Invalid profile');points+=r.length;for(const q of r)if(!Array.isArray(q)||q.length!==2||!q.every(finite)||q.some(n=>Math.abs(n)>5000))throw Error('Invalid profile coordinates');if(r[0].some((v,i)=>v!==r.at(-1)[i]))throw Error('Profile must be closed');}}if(points>40000)throw Error('Project too complex');};if(f.keepouts!==undefined){if(!Array.isArray(f.keepouts)||f.keepouts.length>50)throw Error('Maximum 50 no-cut areas');for(const z of f.keepouts){if(typeof z.id!=='string'||z.id.length>100||typeof z.name!=='string'||z.name.length>60)throw Error('Invalid no-cut area');shape(z.shape);}}const photo=validPhoto(f.photo);for(const t of data.tools){if(typeof t.name!=='string'||!t.name.trim()||t.name.length>60||typeof t.id!=='string'||!['x','y','rotation','depth'].every(k=>finite(t[k]))||Math.abs(t.x)>5000||Math.abs(t.y)>5000||Math.abs(t.rotation)>3600||t.depth<=0||t.depth>200)throw Error('Invalid tool');shape(t.shape);if(!Array.isArray(t.zones)||t.zones.length>24)throw Error('Invalid depth regions');for(const z of t.zones){if(typeof z.id!=='string'||!finite(z.depth)||z.depth<=0||z.depth>200)throw Error('Invalid region depth');shape(z.shape);}}return clone({foam:{...f,...(photo?{photo}:{})},tools:data.tools,name:typeof data.name==='string'?data.name.slice(0,80):'Drawer'});}
const xml=s=>s.replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));
export function shapeD(shape){return shape.map(p=>p.map(r=>r.map(([x,y],i)=>(i?'L':'M')+x.toFixed(3)+' '+y.toFixed(3)).join(' ')+'Z').join(' ')).join(' ');}
// Locked or overlapping items are cut as one pocket: their outlines merge into nested depth
// layers so overlapping members never export as separate overlapping paths.
function exportGroups(tools){const parent=tools.map((_,i)=>i),find=i=>parent[i]===i?i:(parent[i]=find(parent[i])),join=(a,b)=>{parent[find(a)]=find(b);},shapes=tools.map(t=>posed(t)),boxes=shapes.map(extent);
 for(let i=0;i<tools.length;i++)for(let j=0;j<i;j++){const a=boxes[i],b=boxes[j];if((tools[i].lock&&tools[i].lock===tools[j].lock)||(a.minX<b.maxX&&b.minX<a.maxX&&a.minY<b.maxY&&b.minY<a.maxY&&shapeArea(clip.intersection(shapes[i],shapes[j]))>.01))join(i,j);}
 const groups=[],seen=new Set();for(const [i,t] of tools.entries()){const root=find(i);if(seen.has(root))continue;seen.add(root);const members=tools.filter((_,k)=>find(k)===root);if(members.length>1){groups.push({name:members.map(o=>o.name).join(' + '),regions:depthLayers(members).map((l,k)=>({shape:l.shape,depth:l.depth,zone:k>0}))});continue;}groups.push({name:t.name,regions:[{shape:posed(t),depth:t.depth,zone:false},...zonesFor(t).sort((a,b)=>a.depth-b.depth).map(z=>({shape:posed(t,z.shape),depth:z.depth,zone:true}))]});}return groups;}
export function exportFoamSVG(data,options={}){const {foam,tools}=data;return `<svg xmlns="http://www.w3.org/2000/svg" width="${foam.width}mm" height="${foam.height}mm" viewBox="0 0 ${foam.width} ${foam.height}"><title>${xml(data.name||'Toolnest foam')}</title><desc>Depths are millimetres from foam top. Assign pocket depths in CAM; SVG metadata does not set Easel cutting depths.</desc>${options.alignmentFrame?`<path id="stock-reference-frame" data-depth-mm="0" data-reference-only="true" fill="none" stroke="#b55" stroke-width="0.1" d="M0 0H${foam.width}V${foam.height}H0Z"><title>STOCK REFERENCE ONLY — set depth 0 mm in CAM or remove after alignment</title></path>`:''}${exportGroups(tools).map(g=>`<g data-tool="${xml(g.name)}">${g.regions.map(r=>`<path fill="${r.zone?'#333':'#777'}" fill-rule="evenodd"${r.zone?'':' stroke="none"'} data-depth-mm="${r.depth}" d="${shapeD(r.shape)}"><title>${xml(g.name)}${r.zone?' region':''} — ${r.depth} mm deep</title></path>`).join('')}</g>`).join('')}</svg>`;}
export function exportFoamDXF(data){let a=['0','SECTION','2','HEADER','9','$INSUNITS','70','4','0','ENDSEC','0','SECTION','2','ENTITIES'];for(const g of exportGroups(data.tools))for(const region of g.regions)for(const poly of region.shape)for(const ring of poly){a.push('0','LWPOLYLINE','100','AcDbEntity','8',`DEPTH_${region.depth.toFixed(2).replace('.','_')}_MM`,'100','AcDbPolyline','90',String(ring.length-1),'70','1');for(const [x,y] of ring.slice(0,-1))a.push('10',x.toFixed(4),'20',(data.foam.height-y).toFixed(4));}return [...a,'0','ENDSEC','0','EOF'].join('\n')+'\n';}
export function depthCSV(data){const quote=s=>'"'+String(s).replaceAll('"','""')+'"';return 'Tool,Region,Depth from top (mm)\n'+data.tools.flatMap(t=>[[t.name,'Pocket',t.depth],...zonesFor(t).map((z,i)=>[t.name,`Deeper region ${i+1}`,z.depth])]).map(row=>row.map(quote).join(',')).join('\n')+'\n';}

export function camSetup(data,{alignmentFrame=false}={}){const f=data.foam,lines=['TOOLNEST · CAM SETUP',`Stock: ${f.width} × ${f.height} × ${f.thickness} mm`,`Project: ${data.name}`,'Units: millimetres. Do not auto-scale or fit the design to material.','Physical XY origin: bottom-left corner of the foam, viewed as shown in Toolnest.','Z reference: top of foam. Pocket depths are measured downward from this surface.','Fixture the same foam in the same orientation, set the machine origin to that physical corner, and check two known positions before cutting.','SVG/DXF may be repositioned by CAM import. Verify overall dimensions and the placement table below. Relative tool placement is encoded; machine registration is not automatic.',alignmentFrame?'SVG includes a stock-sized REFERENCE FRAME. Set its depth to 0 mm or delete it after positioning. It must not be cut.':'No stock outline is included as a cutting entity. Use the placement table to position the imported design.','Easel SVG/DXF: select filled pocket cuts; assign every base/region depth from the depth CSV. SVG metadata and DXF layers do not apply Easel machining depths.','Easel Pro STL: import as millimetres; disable Scale model to fit material and verify width, length and thickness. Preserve the model Z scale. Reposition the model to the physical stock origin.','The STL represents the designed foam surface and depth steps; it contains no toolpaths, feed rates or cutter compensation.','Existing photo pockets and no-cut layout zones are references, not pre-machined surfaces or clamp avoidance toolpaths. Check clamp clearance, tool reach, bit diameter, Z safe heights and the CAM simulation.','', 'TOOL PLACEMENT · bounding box, X from left / Y from bottom'];for(const t of data.tools){const b=extent(posed(t));lines.push(`${t.name}: X=${b.minX.toFixed(3)} Y=${(f.height-b.maxY).toFixed(3)} W=${(b.maxX-b.minX).toFixed(3)} L=${(b.maxY-b.minY).toFixed(3)} mm; base pocket ${t.depth} mm`);}lines.push('','Photo background and no-cut annotations are excluded from machining exports. Verify a test pocket before the final foam.');return lines.join('\n')+'\n';}
